class Solution:
    def checkValidGrid(self, grid: List[List[int]]) -> bool:
        if grid[0][0] != 0:
            return False
        n = len(grid)
        pos = [None] * (n * n)
        for r in range(n):
            for c in range(n):
                pos[grid[r][c]] = (r, c)
        for t in range(1, n * n):
            dr = abs(pos[t][0] - pos[t - 1][0])
            dc = abs(pos[t][1] - pos[t - 1][1])
            if not ((dr == 1 and dc == 2) or (dr == 2 and dc == 1)):
                return False
        return True

