class Solution {
public:
    bool checkValidGrid(vector<vector<int>>& grid) {
        if (grid[0][0] != 0) return false;
        int n = grid.size();
        vector<pair<int,int>> pos(n * n);
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++)
                pos[grid[r][c]] = {r, c};
        for (int t = 1; t < n * n; t++) {
            int dr = abs(pos[t].first - pos[t-1].first);
            int dc = abs(pos[t].second - pos[t-1].second);
            if (!((dr == 1 && dc == 2) || (dr == 2 && dc == 1))) return false;
        }
        return true;
    }
};

